}

test_suite:
test('initial value is 0', () => {
  const { result } = renderHook(() => useRafValue(500));
  expect(result.current.value).toBe(0);
});

test('isRunning starts false', () => {
  const { result } = renderHook(() => useRafValue(500));
  expect(result.current.isRunning).toBe(false);
});

test('reset() sets value back to 0', () => {
  const { result } = renderHook(() => useRafValue(500));
  act(() => result.current.start());
  act(() => result.current.reset());
  expect(result.current.value).toBe(0);
  expect(result.current.isRunning).toBe(false);
});

test('start() sets isRunning to true', () => {
  const { result } = renderHook(() => useRafValue(1000));
  act(() => result.current.start());
  expect(result.current.isRunning).toBe(true);
});

// __hidden__
test('value is between 0 and 1', () => {
  const { result } = renderHook(() => useRafValue(100));
  expect(result.current.value).toBeGreaterThanOrEqual(0);
  expect(result.current.value).toBeLessThanOrEqual(1);
});

solution:
import { useState, useRef, useCallback } from 'react';

export function useRafValue(duration: number) {
  const [value, setValue] = useState(0);
  const [isRunning, setIsRunning] = useState(false);
  const startTime = useRef<number | null>(null);
  const rafId = useRef<number>(0);

  const start = useCallback(() => {
    setIsRunning(true);
    startTime.current = null;
    const animate = (now: number) => {
      if (startTime.current === null) startTime.current = now;
      const elapsed = now - startTime.current;
      const progress = Math.min(elapsed / duration, 1);
      setValue(progress);
      if (progress < 1) {
        rafId.current = requestAnimationFrame(animate);
      } else {
        setIsRunning(false);
      }
    };
    rafId.current = requestAnimationFrame(animate);
  }, [duration]);

  const reset = useCallback(() => {
    cancelAnimationFrame(rafId.current);
    startTime.current = null;
    setValue(0);
    setIsRunning(false);
  }, []);

  return { value, start, reset, isRunning };
}
